// Infrastructure/ClockEntryDataQueries.cs
using Microsoft.EntityFrameworkCore;

public static class ClockEntryDataQueries
{
    public static IQueryable<ClockEntryEntity> CompletedForEmployee(TimeClockDbContext dbContext, int employeeId)
    {
        return dbContext.ClockEntries.Where(entry => entry.EmployeeId == employeeId && entry.Clockout != null);
    }

    public static Task<List<ClockEntryEntity>> MaterializeAsync(IQueryable<ClockEntryEntity> query, CancellationToken cancellationToken = default)
    {
        return query.ToListAsync(cancellationToken);
    }
}

// Tests/ClockEntryDataQueriesTests.cs
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public sealed class ClockEntryDataQueriesTests
{
    [Fact]
    public async Task CompletedForEmployee_WhenMaterialized_ReturnsOnlyMatchingCompletedEntries()
    {
        await using SqliteConnection connection = new("Data Source=:memory:");
        await connection.OpenAsync();
        DbContextOptions<TimeClockDbContext> options = new DbContextOptionsBuilder<TimeClockDbContext>().UseSqlite(connection).Options;
        await using TimeClockDbContext dbContext = new(options);
        await dbContext.Database.EnsureCreatedAsync();

        int targetEmployeeId = 19;
        DateTime start = new(2026, 8, 15, 9, 0, 0);
        ClockEntryEntity completedEntry = new() { EmployeeId = targetEmployeeId, ClockIn = start, Clockout = start.AddHours(4) };
        ClockEntryEntity openEntry = new() { EmployeeId = targetEmployeeId, ClockIn = start.AddDays(1) };
        ClockEntryEntity completedEntryForOtherEmployee = new() { EmployeeId = 20, ClockIn = start, Clockout = start.AddHours(4) };
        await dbContext.AddRangeAsync(completedEntry, openEntry, completedEntryForOtherEmployee);
        await dbContext.SaveChangesAsync();

        IQueryable<ClockEntryEntity> query = ClockEntryDataQueries.CompletedForEmployee(dbContext, targetEmployeeId);
        List<ClockEntryEntity> results = await ClockEntryDataQueries.MaterializeAsync(query);
        ClockEntryEntity result = Assert.Single(results);
        Assert.Same(completedEntry, result);
    }
}
